INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1530017-che200', 'stk-soo', 'CHE 200', 'info', '{"desc": "هذا الموضوع مخصص لمناقشة المقرر المذكور في العنوان\nبنود تساعد في تقييم المقرر:\nجودة المقرر بشكل عام\nالمواضيع التي يغطيها المقرر\nالكتاب المستخدم للمقرر\nالأسئلة والأمثلة المستخدمة في المقرر\nمدى فائدته في الناحية التطبيقية\nولكم الحرية في تقييم المقرر باستحداث بنود أخرى ترونها مناسبه لتقييمه.\n\nكما نرجو تحري الصدق والعدل في تقييم المقرر\nوعدم الخلط بين تقييم الأستاذ وتقييم المقرر بذاته", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-200-principles-of-chem-engineering/183899/1", "user": "SOO", "ts": 1621527307000, "tid": 183899, "pn": 1}}', 1621527307000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533115-che200', 'stk-ahmed1', 'CHE 200', 'info', '{"desc": "جودة المقرر بشكل عام: المقرر مهم للمهندس الكيميائي راح تتعلم تسوي ماتيريال بلانس و انرجي بلانس\nالمواضيع التي يغطيها المقرر:\n- شابتر 2: مافيه الا تحويل وحدات ومقدمة بسيطة في الكورس.\n- شابتر 3: شابتر بسيط راح تتعلم فيه التحويل من المول فراكشن للماس فراكشن والعكس وبعض الامور المهمة مثل السبسفيك قرافيتي و الماس والفلويوم فلو ريت واللي راح تستعملها بعدين في الكورس.\n- شابتر 4: شابتر مهم جدا جدا ويمكن هذا اهم شابتر في الكورس واصعب شابتر، في البداية راح تتعلم انواع العمليات وبعدها راح تسوي ماس بلانس على السنقل يونت وبعدها على الملتبل يونت و بتتعلم شنو الباي باس و الريسايكل واخيرا راح تاخذ الماس بلانس على الرياكتف سستم ( اصعب شي في الشابتر) و الإحتراق الكامل والإحتراق الجزئي.\nمثل ما قلت الشابتر ذا يحتاج شغل محترم فحاول تركز في مذاكرتك له.\nإلى هذا الجزء عندك شرح دكتور باسم أبو السعود في اليوتيوب شرحه جدا ممتاز ويغنيك عن الدكتور.\n- شابتر7: راح تاخذ انواع الطاقة والانثالبي و الهيت و الوورك بنوعيها الشافت وورك و الفلو وورك، وكيف تستخدم الجداول اللي في نهاية الكتاب اللي هي B.5 -B.7 وبعدها راح تبدا تسوي انرجي بلانس. شابتر متوسط الصعوبة.\n-شابتر 8: هنا راح تتعلم تسوي الجدول بنفسك، طبعا الجداول اللي فوق ذيك للماء فقط، للمواد الثانية انت راح تسويها وكيف تحسب الانثالبي و الانترنال انرجي، و بتدرس كيف تطلع المعلومات من ال psychrometric chart في هذا الشابتر راح تستخدم ثلاث جداول اللي هي B.1, B.2 and B.8 . شابتر متوسط الصعوبة.\n-شابتر 9: راح تتعلم فيه heat of reaction, heat of formation و heat of combustion وبعدها راح تاخذ طريقتين في حساب الانثالبي بإستخدام ال heat of reaction method و ال heat of formation method. شابتر سهل وراح تحتاج مراجعة الرياكتف سستم اللي في شابتر 4.\nالكتاب المستخدم للمقرر:\nhttps://www.google.com/url?sa=i&url=https%3A%2F%2Fwww.wiley.com%2Fen-sa%2FFelder%2527s%2BElementary%2BPrinciples%2Bof%2BChemical%2BProcesses%252C%2B4th%2BEdition%252C%2BGlobal%2BEdition-p-9781119249214&psig=AOvVaw2wx-_dzU3lteUQ4ym0KBiM&ust=1640060514403000&source=images&cd=vfe&ved=0CAsQjRxqFwoTCIiQstXD8fQCFQAAAAAdAAAAABAD\nFelder’s Elementary Principles of\n.Chemical Processes, Global Edition (blue cover), Wiley (2017)\n\nالأسئلة والأمثلة المستخدمة في المقرر: امثلة الكتاب جيدة، طبعا حاول تحل الواجب بنفسك لانه راح يسهل عليك فهم المنهج وكيف ممكن يجيبون عليه اسئلة وان شاء بتبدع في الكورس.\n\nنصيحة اخيرة الكورس طويل فحاول ما تسوف فيه ويفضل انك تسوي ملخص لكل شابتر عشان تذاكر منه للفاينل، الترم هذا الفاينل كان شامل للمنهج كامل وفالكم ال +A", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-200-principles-of-chem-engineering/183899/2", "user": "Ahmed1", "ts": 1639974498000, "tid": 183899, "pn": 2}}', 1639974498000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_h-che200', 'stk-saleh_h', 'CHE 200', 'doc', '{"docs": [{"id": "stk-dr-f182604", "n": "Dr. Abdul Gani Abdul Jameel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 200 - Term 211\nالتحضير : يحضر بداية المحاضرة ويمشي التأخير الى 10 دقايق تقريبا، واللي يتاخر يحضره نهاية الكلاس.\nطريقة الشرح : شرحه عادي صراحة لكن لو تركز معه بتفهم.\nالكويزات : الكويزات متوسطة الى صعبة وغالبا الاسئلة تتكرر من الاترام اللي فاتت( تحصلونها بالريسورس او درايف CHE Club).\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B+\nالصوت: الصوت واطي وتحتاج تجلس قدام عشان تسمعه.\nإضافات : الدكتور حيبيب ومتفهم لظروف الطلاب ومرن بموضوع اوقات الكويزات، وأحسن شي لقيته بالدكتور تصحيحه أسطوري بشكل ما تتخيله، باختصار اكتب اي شي ويدفك دف بالبارشيال وما يظلمك ابدا بالدرجات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533443-che200", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdul-gani-abdul-jameel/182604/7", "user": "Saleh_H", "ts": 1642082460000, "tid": 182604, "pn": 7}}]}', 1642082460000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-silence-che200', 'stk-silence', 'CHE 200', 'doc', '{"docs": [{"id": "stk-dr-f182604", "n": "Dr. Abdul Gani Abdul Jameel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE200 (T231) & CHE204 (T232)\n\nالتحضير :\nشديد في التحضير, يحضر اول مايدخل الكلاس مباشرة على الباركود, لكن آخر الترم حذف 3 غيابات في كل المادتين\n\nطريقة الشرح :\nيشرح من السلايدات و يكتب على السبورة عند حل الأمثلة, الشرح جيد للكونسبت و يعطي أمثلة كثير على أرض الواقع, ممتاز في حل الأسئلة بحيث يحل كثير و يعطيك الخطوات بالتفصيل في طرق الحل بالأختبارات و يقولك كيف ممكن تنسأل و ايش المتوقع منك, الدكتور يحب يعطيك الزبدة من بين حشو الكلام الي بعض الأحيان يجي ف يفضل تكتب معه لأن راح يريحك كثير بالمذاكرة خصوصا في الفلويد, الدكتور مايرفع السلايدات الا بعد ماينهي التشابتر بحيث يحشركم بالأسئلة ثم يعطيكم الإجابة\n\nالكويزات :\nغالباً سهلة و بعض الأحيان متوسطة\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA\n\nالصوت:\nممتاز + يستخدم مايك مدري ليه\n\nإضافات :\nالدكتور متعاون و حليل مع الطلاب, يحب ان الكل مركز و منتبه معه ف راح يستقعد اذا شاف احد عالجوال, متساهل في تأجيل مواعيد الكويزات و غالبا يشاوركم قبل يقرر الموعد, الدكتور أخذت معه هالمادتين و أنصح فيه الحقيقة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1538836-che200", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdul-gani-abdul-jameel/182604/8", "user": "Silence", "ts": 1736376510501, "tid": 182604, "pn": 8}}]}', 1736376510501, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s.q-che200', 'stk-s.q', 'CHE 200', 'doc', '{"docs": [{"id": "stk-dr-f182630", "n": "Dr. Wasif Farooq", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "WASIF FAROOQ\n\nCHE 200 Term 211\n\nالتحضير :اخر 5 دقايق يفتح الكشف من ال BB وينادي الاسماء ، ما عنده شي اسمه تأخير يا حاضر او غايب\n\nطريقة الشرح : يفتح السلايدات ويشرح منها ويحل الامثلة على السبورة ، شرحه من عادي الى جيد الدكتور ما شاء الله متمكن من المادة وخابز مواد التخصص خبز لكن مشكلته يلخبط كثير في حل المسائل وبعض الاحيان ما يوصل المعلومة بشكل بسيط وبما انه ملم بمجالات العمل للمهندس الكيميائي ف حتلاقيه يخرج عن موضوع الكلاس ويتكلم في سوق العمل\n\nالكويزات : اختبرنا 5 كويزات وحذف اسوء واحد ، اول 3 كويزات كانت ف ال BB وكانت خيارات ورتن، والرابع والخامس كانوا ورقي والكويز الرابع كله رتن والخامس كله خيارات ، مستوى الكويزات متوسط ذاكر السلايدات الي يرفعها الدكتور على ال BB و امورك فالسليم ان شاء الله\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B\n\nالصوت: اكسنت هندي منخفض نوعا ما لازم تقعد قدام\n\nإضافات :\n1- الدكتور طيب جدا و ما يهتم بالتحضير بتاتا مجرد انك رديت عليه بعد ما ينادي اسمك انت كذا حاضر حتى لو جيت ف نص وقت الكلاس\n\n2- الدكتور يحب الي يشاركون معه ويسألونه ويحفظ اسماؤهم و يتقبل اي سؤال حتى لو كان بديهي واذا شافك منت مركز معه و ما تشارك بيستلمك طول الكلاس اسئلة ويذب عليك على خفيف", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533345-che200", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wasif-farooq/182630/5", "user": "S.Q", "ts": 1641550370000, "tid": 182630, "pn": 5}}]}', 1641550370000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-che200', 'stk-ahmed1', 'CHE 200', 'doc', '{"docs": [{"id": "stk-dr-f184409", "n": "Dr. Muhammad Siddiquee", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معاه CHE 200 في ترم 211\n\nالتحضير : متساهل جدا في التحضير، يحضر في نهاية الكلاس او بدايته ولو قلت له يحضرك وانت جاي متأخر ما بيقول شي، من كثر ماهو متساهل بعض الطلاب للأسف بس يجون وقت التحضير ويمشون بعدها 😅\nطريقة الشرح : يشرح من سلايداته، شرح متواضع بس يحاول يسوي اللي عليه، شرحه في بعض الدروس كان جيد للامانة بس الاغلب محد كان يفهم معاه\nالكويزات : سهلة جدا وافرج كويزاته في حدود الثمانين وفي النهاية مافيه نورمالايزيشن 👍\nالمياجر: ميجر 1 كان جدا تافه الافرج في سكاشن صديقي 82\nميجر 2 كان صعب وافرج سكاشنه 54\nالفاينلات : متوسط المستوى\nالقريد النهائي: اعطيه A الصراحة من ناحية انه متساهل في التحضير و تصحيحه في الكويزات رهيب بس اذا اخذنا الشرح في الإعتبار تقييمه B، عموما لو شفته في كورسات جاية ما بنزل معاه\nالصوت: واضح\nإضافات : الدكتور جدا طيب ومحترم ويدف من ناحية الدرجات، اسئلته في المياجر سهلة و تقيس الفهم ما فيها شي صعب يعني، ما عنده مشكلة لو تمسك الجوال في الكلاس وحتى انه كان يشرح ل اقل من 10 طلاب في الكلاس بس 😅.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533169-che200", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-siddiquee/184409/2", "user": "Ahmed1", "ts": 1640432213000, "tid": 184409, "pn": 2}}]}', 1640432213000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-k.q-che200', 'stk-k.q', 'CHE 200', 'doc', '{"docs": [{"id": "stk-dr-f184409", "n": "Dr. Muhammad Siddiquee", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مادة CHE200 دكتور محمد صديقي\n\nترم 211\n\nالتحضير : جدا متساهل يحضرك حتى لو متاخر نص ساعة.\n\nطريقة الشرح : شرحه الصراحة سيء ولا افهم منه فخذيتها سلف ستدي وطلعت بقريد حلو الحمدلله.\n\nالكويزات : سهلة ولا فيه نورملايزيشن على كلامه فالدبارتمنت.\n\nالمياجر: كومن لكن التصحيح من كل الدكاترة. كل دكتور يمسك بارت كامل لحاله.\n\nالميجر الاول: مكس رتن وخيارات وكان سهل\n\nالميجر الثاني: رتن كامل ما كان صعب لكن كان مرررررررررة طوييييييل الى درجة فيه طلاب واجد ما قدرو يكملونه من كثرماهو مرهق وطويل والوقت ما كفى لانه تقريبا طلب منك كل شي درسته.\n\nالفاينلات : كومن وكان رتن كامل (اوبن بوك)\n\nالتصحيح: مزاجي صراحه لكن لا باس به.\nالميجر الاول صراحة خسف بي اما الميجر الثاني والفاينال تصحيحه عادي لا باس فيه.\n\nالقريد النهائي: B\n\nالصوت: خافت شوي والاكسنت بنقالي\n\nإضافات : الدكتور انصحك به اذا بتاخذ المادة سلف ستدي. جدددا محترم ومتفهم واخلاقه جدا عالية ومتواجد على طولفالاوفس اور ويرد عالايميلات بدون تاخير. تقدر تقول عيبه الوحيد هو الشرح. والتصحيح مختلف من طالب لطالب. لكن بشكلعام يمشي الحال. ومعلومة مهمة الاوبن بوك مرررة فادني فالفاينال الى درجة فيه سؤالين الى ٣ كاملة جت كوبي بيست مع اختلاف الارقام فقط.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533297-che200", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-siddiquee/184409/3", "user": "K.Q", "ts": 1641317224000, "tid": 184409, "pn": 3}}]}', 1641317224000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
